package com.tekwatt.admin.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="admin_actions")public class AdminAction{@Id private UUID id;@Column(nullable=false)private UUID actorId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private AdminActionType actionType;@Column(nullable=false,length=100)private String targetId;@Column(nullable=false,length=500)private String reason;@Column(columnDefinition="TEXT")private String requestPayload;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AdminActionStatus status;private Integer responseStatus;@Column(columnDefinition="TEXT")private String responsePayload;@Column(length=1000)private String errorMessage;@Column(nullable=false,updatable=false)private Instant createdAt;private Instant completedAt;protected AdminAction(){}public AdminAction(UUID actor,AdminActionType type,String target,String reason,String payload){id=UUID.randomUUID();actorId=actor;actionType=type;targetId=target;this.reason=reason;requestPayload=payload;status=AdminActionStatus.PENDING;createdAt=Instant.now();}public void succeed(int code,String response){status=AdminActionStatus.SUCCESS;responseStatus=code;responsePayload=response;completedAt=Instant.now();}public void fail(Integer code,String error){status=AdminActionStatus.FAILED;responseStatus=code;errorMessage=trim(error);completedAt=Instant.now();}private String trim(String value){String text=value==null?"Administrative action failed":value;return text.substring(0,Math.min(text.length(),1000));}public UUID getId(){return id;}public UUID getActorId(){return actorId;}public AdminActionType getActionType(){return actionType;}public String getTargetId(){return targetId;}public String getReason(){return reason;}public String getRequestPayload(){return requestPayload;}public AdminActionStatus getStatus(){return status;}public Integer getResponseStatus(){return responseStatus;}public String getResponsePayload(){return responsePayload;}public String getErrorMessage(){return errorMessage;}public Instant getCreatedAt(){return createdAt;}public Instant getCompletedAt(){return completedAt;}}
